import{_ as l,C as e,o as r,c as d,j as t,a as i,E as s,a3 as h}from"./chunks/framework.D4-ViStF.js";const y=JSON.parse('{"title":"坐忘论·敬信","description":"坐忘论第一篇精读：信为道根、敬为德蒂；有形之物尚且难信，何况无形之道；信敬必须落实为勤行。","frontmatter":{"title":"坐忘论·敬信","description":"坐忘论第一篇精读：信为道根、敬为德蒂；有形之物尚且难信，何况无形之道；信敬必须落实为勤行。","category":"guide","aliases":["坐忘论敬信","敬信一","坐忘论精读之二"],"source":["坐忘论","司马承祯"],"outline":[2,3]},"headers":[],"relativePath":"daoism/daoist-classics/zuowang-lun/chapter-01.md","filePath":"daoism/daoist-classics/zuowang-lun/chapter-01.md","lastUpdated":1789714390000}'),g={name:"daoism/daoist-classics/zuowang-lun/chapter-01.md"};function c(u,a,b,m,x,k){const p=e("DaoReadingPrelude"),n=e("DaoTextReading"),o=e("DaoKeywordCards");return r(),d("div",null,[a[0]||(a[0]=t("h1",{id:"坐忘论·敬信",tabindex:"-1"},[i("坐忘论·敬信 "),t("a",{class:"header-anchor",href:"#坐忘论·敬信","aria-label":'Permalink to "坐忘论·敬信"'},"​")],-1)),s(p,{title:"信是道之根，敬是德之蒂",summary:"第一篇解决的不是技巧，而是方向：若不信坐忘是修道要门，一遇困难便会退转。但「敬信」不是盲信——它要求认可其价值、尊重其方法、亲自实行，再由实践验证。它同时提前给出了全书的终极境界：内不觉其身，外不知宇宙，与道冥一。",points:[{label:"立根蒂",text:"根深则道可长，蒂固则德可茂。"},{label:"破反例",text:"卞和以玉致刖、伍子以言从诛——形器已著而心绪反迷。"},{label:"归勤行",text:"信、敬之外，还要「加之勤行」，得道方必。"}],hint:"此篇可与《天隐子·神仙一》对读：一篇说人本有灵气，一篇说信敬是修道之根，同是「先正见地」。"}),a[1]||(a[1]=t("h2",{id:"【原典层】原文",tabindex:"-1"},[i("【原典层】原文 "),t("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),a[2]||(a[2]=t("p",null,[t("strong",null,"一、信敬是道德的根蒂")],-1)),s(n,{paragraphs:["夫信者道之根，敬者德之蒂，根深则道可长，蒂固则德可茂。"]}),a[3]||(a[3]=t("p",null,[t("strong",null,"二、有形之物尚且不被相信")],-1)),s(n,{paragraphs:["然则璧耀连城之彩，卞和致刖。言开保国之效，伍子从诛。","斯乃形器著而心绪迷，理事萌而情思忽。","况至道超于色味，真性隔于可欲，而能闻希微以悬信，听罔象而不惑者哉。"]}),a[4]||(a[4]=t("p",null,[t("strong",null,"三、敬信坐忘，勤行得道")],-1)),s(n,{paragraphs:["如人闻坐忘之言，信是修道之要，敬仰尊重，决定无疑者，加之勤行，得道必矣。","故庄云：隳支体，黜聪明，离形去智，同于大通，是谓坐忘。"]}),a[5]||(a[5]=t("p",null,[t("strong",null,"四、坐忘所忘与信不足之患")],-1)),s(n,{paragraphs:["夫坐忘者，何所不忘哉。内不觉其一身，外不知乎宇宙，与道冥一，万虑皆遗。","庄云同于大通，此则言浅而意深。","惑者闻而不信，怀宝求宝，其如之何。","经云：信不足焉，有不信。谓信道之心不足，乃有不信之祸及之，何道之可望乎。"]}),a[6]||(a[6]=t("h2",{id:"【原典层】字词释义",tabindex:"-1"},[i("【原典层】字词释义 "),t("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),s(o,{items:[{term:"蒂",pinyin:["dì"],meaning:"花蒂。根深蒂固，喻根基牢固——道以信为根，德以敬为蒂。信解决方向，敬解决态度。"},{term:"卞和致刖",pinyin:["biàn","hé","zhì","yuè"],meaning:"事见《韩非子·和氏》：卞和献玉璞，两代楚王听玉工之言以为石，先后刖其双足。喻真实之宝因识见昏昧而不被承认。"},{term:"伍子从诛",pinyin:["wǔ","zǐ","cóng","zhū"],meaning:"伍子胥谏吴王夫差警惕越国，不被采纳，反受赐死，后越果灭吴。与卞和并列，皆谓才器显著而心绪反迷。"},{term:"形器著",pinyin:["xíng","qì","zhù"],meaning:"形器，有具体形态之物；著，显著。谓对象明明可见可验，心却仍然迷惑。"},{term:"理事萌",pinyin:["lǐ","shì","méng"],meaning:"理事，事物中的道理与征验；萌，开始显露。谓事理与征兆已经显现，人却因情感成见而轻忽。"},{term:"希微",pinyin:["xī","wēi"],meaning:"语本《道德经》第十四章：「听之不闻名曰希，搏之不得名曰微」。指大道无声无形、幽隐难见。"},{term:"悬信",pinyin:["xuán","xìn"],meaning:"悬，悬远、尚未亲见。谓虽未直接证得，仍对幽微之道建立坚定信心——这是初学的起步方式，不是终点。"},{term:"罔象",pinyin:["wǎng","xiàng"],meaning:"无形无象、恍惚幽隐、不能以具体形象限定。可与《庄子·天地》「象罔得玄珠」参看。"},{term:"隳支体",pinyin:["huī","zhī","tǐ"],meaning:"隳，消解、放下；支体，四肢身体。谓放下以身体感受、欲望与边界为中心的执著，非伤害身体。今本《庄子》多作「堕肢体」。"},{term:"黜聪明",pinyin:["chù","cōng","míng"],meaning:"黜，退去其主导地位。谓不把感官分辨与智力计算视为通向大道的最高能力，非教人愚昧。"},{term:"离形去智",pinyin:["lí","xíng","qù","zhì"],meaning:"不再执身形为真实固定的自我，不再执分别判断为认识大道的唯一方式。所去者是「执」，不是正常功能。"},{term:"同于大通",pinyin:["tóng","yú","dà","tōng"],meaning:"大通，无所阻隔、与道贯通。「我与万物绝对对立」的执著暂时消融，非谓事实差别消失。"},{term:"冥一",pinyin:["míng","yī"],meaning:"冥，幽深无形，亦有暗合默契之义；一，合而不分。谓在幽深无迹中与道合一，不留外在痕迹，也无「我成功进入合一」的宣告。"},{term:"万虑皆遗",pinyin:["wàn","lǜ","jiē","yí"],meaning:"种种思虑都被放下，不再留藏于心。遗，非暴力消灭，而是放下、不再承载。"},{term:"怀宝求宝",pinyin:["huái","bǎo","qiú","bǎo"],meaning:"怀中本有宝，却向外求宝。宝指人与生俱来的真性、灵明与道性——道不在外，真性原本是自身之宝。"}]}),a[7]||(a[7]=h("",76))])}const f=l(g,[["render",c]]);export{y as __pageData,f as default};
